import os
import random
import string
from typing import List

# Generator for MMKV instance ID strings and filesystem-like paths.
# Target fuzzers consume:
# - FUZZ_PARAM_STR(): non-empty instance IDs, crypt keys (<=16 bytes are truncated by stub), and other option strings
# - FUZZ_PARAM_FILENAME(): paths where parent directory must exist syntactically (stub extracts dirname and bails if none)
# - Integers: produced by the harness independently, so we only craft the byte stream for string/filename providers.
#
# Strategy:
# - Produce a small corpus of plausible mmapID strings that cover different character classes and lengths.
# - Produce path-like strings with both '/' and '\\' separators and nested components so dirname extraction works.
# - Include some edge-y but valid cases: long names, names with dots, spaces, Unicode, and reserved-like words.
# - Concatenate a sequence of such strings separated by NUL ("\0"). Many fuzz harnesses split the initial buffer
#   into multiple FUZZ_PARAM_STR/FILENAME consumptions by scanning for NULs. Keeping sizes <= 4096.
# - Make results pseudo-random but reproducible via the provided seed.

MAX_TOTAL_BYTES = 4096

def _rand_choice(rng: random.Random, arr: List[str]) -> str:
    return arr[rng.randrange(0, len(arr))]

def _gen_mmap_id(rng: random.Random) -> str:
    # Build diverse IDs
    base_samples = [
        "mmkv", "default", "user", "session", "cache", "prefs", "settings",
        "com.tencent.mmkv", "com.example.app", "org.example", "prod", "dev", "test",
        "a",  # minimal non-empty
    ]
    # Add random alphanum with separators
    alph = string.ascii_letters + string.digits + "-_:."
    # Some unicode samples
    unicode_samples = ["用户", "データ", "данные", "dados", "키값", "Δοκιμή"]

    choice = rng.randint(0, 6)
    if choice == 0:
        return _rand_choice(rng, base_samples)
    elif choice == 1:
        # random length 2..40
        n = rng.randint(2, 40)
        return ''.join(rng.choice(alph) for _ in range(n))
    elif choice == 2:
        # domain-like with subparts
        parts = [
            _rand_choice(rng, ["com", "org", "net", "io", "dev"]),
            ''.join(rng.choice(string.ascii_lowercase) for _ in range(rng.randint(3, 8))),
            ''.join(rng.choice(string.ascii_lowercase) for _ in range(rng.randint(3, 10)))
        ]
        return '.'.join(parts)
    elif choice == 3:
        # include unicode mixed with ascii
        return _rand_choice(rng, base_samples) + "." + _rand_choice(rng, unicode_samples)
    elif choice == 4:
        # path-like id (allowed by API, just a unique string)
        segs = [
            ''.join(rng.choice(alph) for _ in range(rng.randint(1, 6)))
            for _ in range(rng.randint(2, 5))
        ]
        sep = _rand_choice(rng, ['/','-','.'])
        return sep.join(segs)
    elif choice == 5:
        # long but within reasonable limit
        n = rng.randint(50, 120)
        return ''.join(rng.choice(alph) for _ in range(n))
    else:
        # include spaces
        words = [
            _rand_choice(rng, base_samples),
            ''.join(rng.choice(string.ascii_lowercase) for _ in range(rng.randint(3,8)))
        ]
        return ' '.join(words)


def _gen_crypt_key(rng: random.Random) -> str:
    # Crypt key comment says 16 bytes at most; we generate up to 16 bytes characters.
    # Include empty sometimes (stub may choose to pass or not pass key separately).
    if rng.random() < 0.15:
        return ""
    n = rng.randint(1, 16)
    # Prefer full 0-255 bytes? We must stay in UTF-8 safe for str; choose visible ASCII plus some extended.
    # Keys are treated as std::string, so arbitrary bytes okay, but we keep it simple
    pool = string.printable.rstrip()  # no trailing whitespace extremes
    return ''.join(rng.choice(pool) for _ in range(n))


def _gen_dir_components(rng: random.Random) -> List[str]:
    # Components without separators
    comp_pool = [
        "tmp", "var", "data", "mmkv", "backup", "restore", "user", "cache", "prefs",
        "A", "B1", "C_2", "dir.with.dots", "spaced name", "unic_用户",
    ]
    def rand_comp():
        choice = rng.randint(0, 4)
        if choice == 0:
            return _rand_choice(rng, comp_pool)
        elif choice == 1:
            n = rng.randint(1, 10)
            return ''.join(rng.choice(string.ascii_letters + string.digits + "-_ .") for _ in range(n))
        elif choice == 2:
            return f"dir{rng.randint(0,999)}"
        elif choice == 3:
            return "seg" + ''.join(rng.choice(string.ascii_lowercase) for _ in range(rng.randint(1,6)))
        else:
            return "part" + _rand_choice(rng, ["α", "β", "用户", "データ"])  # unicode
    depth = rng.randint(2, 5)
    return [rand_comp() for _ in range(depth)]


def _gen_path(rng: random.Random) -> str:
    # Create a path-like string with both styles occasionally. The stub uses both '/' and '\\' when finding parent.
    comps = _gen_dir_components(rng)
    style = rng.randint(0, 3)
    if style == 0:
        # Unix-like
        path = "/" + "/".join(comps) + "/file.dat"
    elif style == 1:
        # Windows-like with drive
        drive = _rand_choice(rng, ["C:", "D:", "E:"])
        path = drive + "\\" + "\\".join(comps) + "\\file.bin"
    elif style == 2:
        # Mixed separators
        path = "/" + comps[0] + "\\" + comps[1] + "/" + "/".join(comps[2:]) + "/f"
    else:
        # Deep nested
        sep = _rand_choice(rng, ["/", "\\"])
        path = sep + sep.join(comps + ["leaf"])  # ensure has parent
    # Ensure there is at least one separator not at pos 0 for dirname logic; all variants satisfy this.
    return path


def _assemble_buffer(parts: List[str]) -> bytes:
    # Join with NUL so consumer can split deterministically
    b = b"\x00".join(s.encode('utf-8', errors='surrogatepass') for s in parts)
    # Truncate to 4096 if needed, but avoid cutting the last string mid-character. Safe because UTF-8 slicing is OK at arbitrary byte boundary? Better: keep last boundary by dropping last part until within limit.
    if len(b) <= MAX_TOTAL_BYTES:
        return b
    # Drop tail parts until within limit
    out = bytearray()
    first = True
    for s in parts:
        enc = s.encode('utf-8', errors='surrogatepass')
        if first:
            cand_len = len(out) + len(enc)
        else:
            cand_len = len(out) + 1 + len(enc)
        if cand_len > MAX_TOTAL_BYTES:
            break
        if not first:
            out.extend(b"\x00")
        out.extend(enc)
        first = False
    return bytes(out)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    parts: List[str] = []

    # First, produce a couple of plausible root directories to satisfy global-init-requiring stubs elsewhere.
    # Even if harness ignores, harmless. These are consumed as FUZZ_PARAM_FILENAME by various stubs.
    for _ in range(rng.randint(2, 4)):
        parts.append(_gen_path(rng))

    # Produce several mmapIDs to be used by different calls.
    for _ in range(rng.randint(3, 6)):
        parts.append(_gen_mmap_id(rng))

    # Produce crypt keys candidates (the stub may or may not use them, but FUZZ_PARAM_STR can consume them).
    for _ in range(rng.randint(2, 4)):
        parts.append(_gen_crypt_key(rng))

    # More filenames for backup/restore src/dst
    for _ in range(rng.randint(3, 6)):
        parts.append(_gen_path(rng))

    # Ensure at least one very short and one long id late in the stream
    parts.append("x")
    parts.append("L" * 64)

    return _assemble_buffer(parts)

import os
import random
import struct
from typing import List

# This generator produces valid MiniPBCoder payloads that exercise:
# - Encoding of strings (protobuf-like varint length + bytes)
# - Encoding of vectors of strings (repeated string fields)
# - Opaque buffers to wrap into MMBuffer and re-encode
# The produced bytes are standalone payloads suitable for FUZZ_PARAM_STR/FUZZ_PARAM_FILENAME.
# We avoid malformed data and keep size <= 4096.

MAX_TOTAL = 4096

# Helper: protobuf-style varint encoding for unsigned integers
def _uvarint(n: int) -> bytes:
    out = bytearray()
    while True:
        to_write = n & 0x7F
        n >>= 7
        if n:
            out.append(to_write | 0x80)
        else:
            out.append(to_write)
            break
    return bytes(out)

# Minimal protobuf-like wire helpers used by MiniPBCoder-style maps/vectors:
# We will encode a message with fields:
# 1: repeated string (vector of strings)
# 2: single string
# 3: opaque bytes
# These are all length-delimited fields (wire type 2): key = (field_number << 3) | 2

def _key(field_no: int, wire_type: int = 2) -> bytes:
    return _uvarint((field_no << 3) | wire_type)

# Safe random ASCII string with possible NULs and wide byte coverage
def _rand_bytes(rng: random.Random, min_len: int, max_len: int) -> bytes:
    n = rng.randint(min_len, max_len)
    # mix of printable, nulls, and random bytes
    parts: List[bytes] = []
    remaining = n
    while remaining > 0:
        choice = rng.random()
        if choice < 0.5:
            # printable run
            run = min(remaining, rng.randint(1, 32))
            parts.append(bytes(rng.choice(b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 _-./") for _ in range(run)))
            remaining -= run
        elif choice < 0.7:
            parts.append(b"\x00")
            remaining -= 1
        else:
            run = min(remaining, rng.randint(1, 32))
            parts.append(os.urandom(run))
            remaining -= run
    return b"".join(parts)

def _field_string(s: bytes) -> bytes:
    return _key(2) + _uvarint(len(s)) + s

def _field_vec_string(strings: List[bytes]) -> bytes:
    out = bytearray()
    for s in strings:
        out += _key(1)
        out += _uvarint(len(s))
        out += s
    return bytes(out)

def _field_bytes(b: bytes) -> bytes:
    return _key(3) + _uvarint(len(b)) + b

def _build_payload(rng: random.Random) -> bytes:
    # Decide composition
    # Always include at least one string or vector entry.
    include_vec = rng.choice([True, False])
    include_single = rng.choice([True, False])
    include_bytes = rng.choice([True, False])

    # Make sure at least one is included
    if not (include_vec or include_single or include_bytes):
        include_single = True

    chunks: List[bytes] = []

    # Vector of strings
    if include_vec:
        cnt = rng.randint(0, 8)
        # Ensure sometimes empty vector and sometimes many entries
        vec = []
        for i in range(cnt):
            # create diverse strings: empty, short, long, unicode-like
            pick = rng.random()
            if pick < 0.2:
                s = b""
            elif pick < 0.5:
                s = _rand_bytes(rng, 1, 16)
            elif pick < 0.8:
                s = _rand_bytes(rng, 17, 128)
            else:
                # include some multi-byte UTF-8-looking data
                utf_pool = ["你好", "🚀", "κλειδί", "ключ", "árvíztűrő tükörfúrógép"]
                s = rng.choice(utf_pool).encode("utf-8")
            vec.append(s)
        chunks.append(_field_vec_string(vec))

    # Single string
    if include_single:
        pick = rng.random()
        if pick < 0.2:
            s = b""
        elif pick < 0.6:
            s = _rand_bytes(rng, 1, 64)
        else:
            s = _rand_bytes(rng, 65, 512)
        chunks.append(_field_string(s))

    # Opaque bytes
    if include_bytes:
        # Create an inner payload that mimics encoded_from_str to feed the encode(MMBuffer) path
        inner_choice = rng.choice(["plain", "nested_vec"]) 
        if inner_choice == "plain":
            inner = _field_string(_rand_bytes(rng, 0, 256))
        else:
            inner = _field_vec_string([_rand_bytes(rng, 0, 64) for _ in range(rng.randint(1, 6))])
        chunks.append(_field_bytes(inner))

    payload = b"".join(chunks)

    # Cap to MAX_TOTAL (trim last field if necessary), but keep it valid by truncating at field boundaries.
    if len(payload) > MAX_TOTAL:
        # Conservative: rebuild with smaller components
        rng2 = random.Random(rng.randint(0, 2**31-1))
        small_chunks: List[bytes] = []
        for c in chunks:
            if len(b"".join(small_chunks)) + len(c) <= MAX_TOTAL:
                small_chunks.append(c)
            else:
                # try a smaller alternative of the same type by generating small random bytes
                small = _field_string(_rand_bytes(rng2, 0, 16))
                if len(b"".join(small_chunks)) + len(small) <= MAX_TOTAL:
                    small_chunks.append(small)
                break
        payload = b"".join(small_chunks)[:MAX_TOTAL]

    return payload


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Randomly choose among several payload styles to diversify paths
    style = rng.choice(["vector_only", "single_only", "bytes_only", "mixed"]) 

    if style == "vector_only":
        cnt = rng.randint(1, 10)
        vec = [_rand_bytes(rng, 0, 128) for _ in range(cnt)]
        payload = _field_vec_string(vec)
    elif style == "single_only":
        payload = _field_string(_rand_bytes(rng, 0, 1024))
    elif style == "bytes_only":
        inner = _field_string(_rand_bytes(rng, 0, 512))
        payload = _field_bytes(inner)
    else:
        payload = _build_payload(rng)

    if len(payload) > MAX_TOTAL:
        payload = payload[:MAX_TOTAL]

    return bytes(payload)
